/* Rose — a chromatic palette, hue ~345. Deliberately kept distinct from
   danger (hue ~25): 345 reads as pink/magenta, not as an error state. The
   chroma is held a touch lower than danger's so the two never collapse to
   the same red under any viewing condition. Both themes declare all six
   roles. */

:root[data-theme="light"] .palette-rose {
    --palette-base: oklch(0.57 0.18 345);
    --palette-soft: oklch(0.94 0.06 345);
    --palette-line: oklch(0.85 0.07 345);
    --palette-contrast: oklch(1 0 0);
    --palette-accent: oklch(0.48 0.16 345);
    --palette-ring: var(--palette-accent);
}

:root[data-theme="dark"] .palette-rose {
    --palette-base: oklch(0.72 0.16 345);
    --palette-soft: oklch(0.3 0.08 345);
    --palette-line: oklch(0.4 0.1 345);
    --palette-contrast: oklch(0.12 0.02 345);
    --palette-accent: oklch(0.8 0.14 345);
    --palette-ring: var(--palette-accent);
}
